package main

import (
	"fmt"
	"net"
)

func getURLToVisit(domain, subdomainPrefix string) string {
	if subdomainPrefix == "" || subdomainPrefix == "." || subdomainPrefix == "www" {
		return "https://" + domain
	}
	return "https://" + subdomainPrefix + "." + domain
}

func main() {
	tests := []struct {
		domain        string
		subdomain     string
		expectedURL   string
	}{
		{"example.com", "subdomain", "https://subdomain.example.com"},
		{"example.com", "a.b", "https://a.b.example.com"},
		{"example.com", "", "https://example.com"},
		{"example.com", ".", "https://example.com"},
		{"example.com", "www", "https://example.com"},
		{"example.com", "invalid", "https://invalid.example.com"},
	}

	for _, test := range tests {
		result := getURLToVisit(test.domain, test.subdomain)
		if result != test.expectedURL {
			fmt.Printf("Test failed: domain=%s, subdomain=%s, expected=%s, got=%s\n", test.domain, test.subdomain, test.expectedURL, result)
		} else {
			fmt.Printf("Test passed: domain=%s, subdomain=%s, got=%s\n", test.domain, test.subdomain, result)
		}
	}
}
